// Verify QR HMAC Signature and Expiration
const crypto = require('crypto');
const secret = $env.QR_SIGNING_SECRET || 'medconnect-secret';
const payload = $json.body;

const expectedSig = crypto.createHmac('sha256', secret).update(payload.appointment_id + payload.issued_at).digest('hex');
const isValid = (expectedSig === payload.signature) && (new Date(payload.exp) > new Date());

return { json: { ...payload, isValid } };
